/// Given three signed 8-bit integers x, y, and z that satisfy:
///   1 ≤ x, y, z
///   y + 2*z ≤ x
/// compute and return the largest non‐negative integer q such that
/// q * (y + z) ≤ x - z.
/// Equivalently, q = floor((x - z) / (y + z)).
fn solve(x: i8, y: i8, z: i8) -> i8 {
    // Under the preconditions, (x - z) and (y + z) are positive and fit in i8.
    let numerator = x - z;
    let denominator = y + z;
    numerator / denominator
}

